    (V, "volume center", "center = box.min + half;", "center = box.max - half;"),
    (V, "volume center min", "center = box.min + half;", "center = box.min;"),
    (V, "volume radius order", "std::sqrt(half.z * half.z + half.y * half.y + half.x * half.x)", "std::sqrt(half.x * half.x + half.y * half.y + half.z * half.z)"),
    (V, "volume radius no z", "std::sqrt(half.z * half.z + half.y * half.y + half.x * half.x)", "std::sqrt(half.y * half.y + half.x * half.x)"),
    (V, "volume zero", "    volume = S_CollisionVolume();\n", ""),
