    (V, "volume inverse ptr", "volume.invMatrix = &invMatrix;", "volume.invMatrix = &frame->GetMatrix();"),
    (V, "volume frame", "    volume.frame = frame;\n", ""),
    (V, "volume type", "    volume.type = type;\n", ""),
    (V, "volume local scale", "const S_vector scale = frame->GetWorldScale();", "const S_vector scale = frame->GetScale();"),
    (V, "volume scale yz", "scale.y <= scale.z ? scale.z : scale.y;", "scale.y <= scale.z ? scale.y : scale.z;"),
    (V, "volume scale x", "scale.x <= maxYZ ? maxYZ : scale.x;", "maxYZ;"),
    (V, "volume radius unscaled", "volume.radius = maxScale * radius;", "volume.radius = radius;"),
    (V, "volume center local", "volume.center = center * frame->GetMatrix();", "volume.center = center;"),
